import { createChannels } from './channels/index.js';
import { loadConfig } from './config.js';
import { createEventHandler } from './handlers/event-handler.js';
import { createToolAfterHandler, createToolBeforeHandler } from './handlers/tool-handler.js';
import { getMessages } from './i18n/index.js';
import { ensureIconCache } from './icon.js';
import { createNotifier } from './notifier.js';
import { createSessionRegistry } from './session.js';
import { detectTerminal } from './terminal.js';
export const OpencodeNotifier = async ({ client, directory }) => {
    const config = loadConfig();
    const messages = getMessages(config.locale, config.events);
    ensureIconCache();
    const termInfo = detectTerminal(directory);
    const sessions = createSessionRegistry(client, termInfo.projectName);
    const { notify, flush } = createNotifier(createChannels(config, termInfo.icon), termInfo.icon);
    return {
        event: createEventHandler(notify, messages, sessions),
        'tool.execute.before': createToolBeforeHandler(notify, messages, sessions),
        'tool.execute.after': createToolAfterHandler(notify, messages, sessions),
        dispose: flush,
    };
};
//# sourceMappingURL=index.js.map

import { resolveChannelEvents } from '../config.js';
import { createMacOSChannel } from './macos.js';
import { createTelegramChannel } from './telegram.js';
export function createChannels(config, icon) {
    const entries = [];
    if (config.channels.macos?.enabled) {
        entries.push({
            channel: createMacOSChannel(icon),
            events: resolveChannelEvents(config.events, config.channels.macos.events),
        });
    }
    if (config.channels.telegram?.enabled) {
        entries.push({
            channel: createTelegramChannel(config.channels.telegram, config.workspace),
            events: resolveChannelEvents(config.events, config.channels.telegram.events),
        });
    }
    return entries;
}
//# sourceMappingURL=index.js.map

import { en } from './en.js';
import { ko } from './ko.js';
const locales = { en, ko };
const TEMPLATE_VARS = {
    decisionNeeded: 'question',
    subagentStarted: 'description',
    toolExecuting: 'toolName',
    toolCompleted: 'toolName',
};
export function getMessages(locale, events) {
    const base = { ...(locales[locale] || locales.en) };
    for (const [key, options] of Object.entries(events)) {
        if (!options.message) {
            continue;
        }
        const templateVar = TEMPLATE_VARS[key];
        if (templateVar) {
            const template = options.message;
            base[key] = (arg) => template.replaceAll(`{{${templateVar}}}`, arg);
        }
        else {
            base[key] = options.message;
        }
    }
    return base;
}
//# sourceMappingURL=index.js.map
